def parse_demo(txt, n):
    m=re.search(rf'Demo pair {n} input \(\d+x\d+\):\n(.*?)\nDemo pair {n} output \(\d+x\d+\):\n(.*?)(?:\n\nSame instance|\Z)', txt, re.S)
    if not m: print('no match'); return
    def rows(s): return np.array([[int(z) for z in line.split()] for line in s.strip().splitlines() if line.strip()])
    return rows(m.group(1)),rows(m.group(2))
