def comp_seq(I, comps, cid, bg, wall):
    coords=np.argwhere(comps==cid); r0,c0=coords.min(0);r1,c1=coords.max(0)
    dirs=[(r0,c0,1,1),(r0,c1,1,-1),(r1,c0,-1,1),(r1,c1,-1,-1)]
    cand=[]
    for sr,sc,dr,dc in dirs:
      seq=[]
      v=int(I[sr,sc])
      if v==bg:
        seq=[bg];d=1
      else: seq=[v];d=1
      while sr+dr*d>=r0 and sr+dr*d<=r1 and sc+dc*d>=c0 and sc+dc*d<=c1:
        v=int(I[sr+dr*d,sc+dc*d])
        if v in (bg,wall):break
        seq.append(v);d+=1
      score=sum(v!=bg for v in seq)
      cand.append((score,seq))
    return max(cand,key=lambda x:x[0])[1] if max(x[0] for x in cand)>0 else [bg]

